#define _GNU_SOURCE
#include "stock-evdi.c"
int main(void)
{
    evdi_handle handle = calloc(1, sizeof(*handle));
    assert(handle);
    handle->fd = open("/dev/null", O_RDWR);
    assert(handle->fd >= 0);
    void *pixels = calloc(64, 4);
    assert(pixels);
    evdi_register_buffer(handle, (struct evdi_buffer){.id=0, .buffer=pixels, .width=8, .height=8, .stride=32});
    free(pixels);
    evdi_close(handle);
    return 0;
}
